const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
if (!reduced) {
  try {
    const THREE = await import(
      "https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js"
    );
    const mount = document.getElementById("tree-webgl");
    const renderer = new THREE.WebGLRenderer({
      alpha: true,
      antialias: true,
      powerPreference: "low-power",
    });
    renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.75));
    renderer.setClearColor(0x000000, 0);
    mount.appendChild(renderer.domElement);
    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 100);
    camera.position.z = 10;
    const texture = new THREE.TextureLoader().load(
      "data:image/svg+xml;base64,",
    );
    texture.colorSpace = THREE.SRGBColorSpace;
    const geom = new THREE.PlaneGeometry(1, 1);
    const layers = [
      {
        z: -0.9,
        opacity: 0.009,
        color: 0xbc5cff,
        offsetX: -0.06,
        offsetY: 0.035,
        scale: 1.07,
      },
      {
        z: -0.5,
        opacity: 0.0115,
        color: 0x25f4ff,
        offsetX: 0.04,
        offsetY: -0.02,
        scale: 1.035,
      },
      {
        z: 0,
        opacity: 0.0295,
        color: 0xffffff,
        offsetX: 0,
        offsetY: 0,
        scale: 1,
      },
    ];
    const planes = layers.map((v) => {
      const mat = new THREE.MeshBasicMaterial({
        map: texture,
        color: v.color,
        transparent: true,
        opacity: v.opacity,
        depthWrite: false,
        side: THREE.DoubleSide,
      });
      const obj = new THREE.Mesh(geom, mat);
      obj.position.set(v.offsetX, v.offsetY, v.z);
      scene.add(obj);
      return { obj, v };
    });
    let targetX = 0,
      targetY = 0,
      currentX = 0,
      currentY = 0;
    function resize() {
      const w = innerWidth,
        h = innerHeight;
      renderer.setSize(w, h, false);
      const viewHeight = 10,
        aspect = w / h;
      camera.left = (-viewHeight * aspect) / 2;
      camera.right = (viewHeight * aspect) / 2;
      camera.top = viewHeight / 2;
      camera.bottom = -viewHeight / 2;
      camera.updateProjectionMatrix();
      const baseWidth =
        w < 860 ? viewHeight * aspect * 2.65 : viewHeight * aspect * 1.85;
      const baseHeight = (baseWidth * 1555) / 2110;
      planes.forEach(({ obj, v }) => {
        obj.scale.set(baseWidth * v.scale, baseHeight * v.scale, 1);
      });
    }
    resize();
    window.addEventListener("resize", resize, { passive: true });
    window.addEventListener(
      "pointermove",
      (e) => {
        if (e.pointerType === "touch") return;
        targetX = e.clientX / innerWidth - 0.5;
        targetY = e.clientY / innerHeight - 0.5;
      },
      { passive: true },
    );
    let active = true;
    document.addEventListener("visibilitychange", () => {
      active = !document.hidden;
      if (active) requestAnimationFrame(frame);
    });
    function frame() {
      if (!active) return;
      const breathe = Math.sin(performance.now() / 11500);
      currentX += (targetX - currentX) * 0.008;
      currentY += (targetY - currentY) * 0.008;
      planes.forEach(({ obj, v }, i) => {
        const d = i / 2;
        obj.position.x =
          v.offsetX +
          currentX * (0.12 + d * 0.18) +
          breathe * (i === 0 ? -0.012 : i === 1 ? 0.009 : 0);
        obj.position.y =
          v.offsetY -
          currentY * (0.1 + d * 0.14) +
          breathe * (i === 0 ? 0.006 : 0);
        obj.material.opacity =
          v.opacity * (1 + breathe * (i === 2 ? 0.03 : 0.09));
      });
      renderer.render(scene, camera);
      requestAnimationFrame(frame);
    }
    texture.image?.addEventListener?.("load", () => {}, { once: true });
    // Preserve original SVG as fallback until the texture is ready.
    const check = () => {
      if (texture.image?.complete && texture.image?.naturalWidth) {
        document.getElementById("tree-fallback").classList.add("is-hidden");
      } else requestAnimationFrame(check);
    };
    check();
    frame();
  } catch (err) {
    console.warn("3D disabled; showing original tree SVG", err);
  }
}
